function cost=costfun()
% Cost
% Old q without inert anode pricing
%q=[50.79,28.64,5.1,.45,0,0,0,1;68.43,0,5.1,.4095,0,0,0,1;0,5.46,0,0,.48,1.6,0,1;1.2,21.2,0,0,0,1.6,0,1;5.7,0,0,0,0,1.6,.044,1];
% New q
q=[50.79,28.64,5.1,.45,0,0,0,1;68.43,0,5.1,.4095,0,0,0,1;0,5.46,0,0,.48,1.6,0,1;1.2,21.2,0,0,0,1.6,0,1;5.7,0,0,0,0,1.6,.044,1];

cost=[15,5,32,520,287,113,5000,230]';
eachcost=q.*[cost';cost';cost';cost';cost'];
total=q*cost;
factor=linspace(1e-5,2+2/3,100);
inds=[1,7]; % Indices of factors that scale
res=zeros(length(factor),9);
for i=1:length(factor)
    res(i,1)=factor(i);
    cost1=cost;
    cost1(inds)=cost1(inds)*factor(i);
    total=[q*cost1]';
    res(i,2:6)=total;
    res(i,7)=min(res(i,2:3)); % minimum Al cost
    res(i,8)=min(res(i,4:6)); % minimum steel cost
    res(i,9)=res(i,7)/res(i,8);
end
cost=[];
cost(:,1)=res(:,1)*15; % electricity $/GJ
cost(:,2:6)=res(:,2:6);
end